"""Differential mutation testing: C++ load() verdict vs the independent checker."""
import copy, json, random, sys
sys.path.insert(0, '/workspace/tmp')
import cli, pyref

FRONTEND_SHAPE = 'shape'


def shape_ok(img):
    try:
        if set(img) != set('root front16 front64 cells banks bitmaps nexthops'.split()):
            return False
        if img['root'] is not None and not (len(img['root']) == 2 and 0 <= img['root'][0] <= 10 and 0 <= img['root'][1] <= 131071):
            return False
        for nm, w in (('front16', 4), ('front64', 16)):
            if len(img[nm]) > 4096:
                return False
            for e in img[nm]:
                if len(e) != 3 or not isinstance(e[0], str) or len(e[0]) != w:
                    return False
                if not (0 <= e[1] <= 10 and 0 <= e[2] <= 131071):
                    return False
        if len(img['cells']) != 11 or len(img['banks']) != 11:
            return False
        tot = 0
        for c, b in zip(img['cells'], img['banks']):
            if not isinstance(c, int) or not 0 <= c <= 131072:
                return False
            if len(b) > 65536:
                return False
            tot += len(b)
            for w in b:
                if not isinstance(w, str) or len(w) != 64:
                    return False
        if tot > 65536:
            return False
        if len(img['bitmaps']) > 8193 or len(img['nexthops']) > 8192:
            return False
        for x in img['bitmaps']:
            if not isinstance(x, str) or len(x) != 16:
                return False
        for x in img['nexthops']:
            if not isinstance(x, int) or not 0 <= x <= 4194302:
                return False
        return True
    except Exception:
        return False


def load_verdict(binary, img):
    ops = [['load', img]]
    r = cli.run_request({'cases': [{'ops': ops}]}, binary)
    if 'error' in r:
        return 'invalid-request'
    return r['results'][0]['loads'][0]


def py_verdict(img):
    try:
        pyref.validate(img)
        return True
    except pyref.Bad:
        return False
    except Exception as e:
        return 'py-crash:%r' % e


def mutate_word(rng, img):
    img = copy.deepcopy(img)
    s = rng.randrange(11)
    if not img['banks'][s]:
        return None
    r = rng.randrange(len(img['banks'][s]))
    w = int(img['banks'][s][r], 16)
    b = rng.randrange(256)
    img['banks'][s][r] = format(w ^ (1 << b), '064x')
    return img


def mutate_random(rng, img):
    kind = rng.choice(['word', 'word', 'word', 'cells', 'rows', 'bitmaps', 'ni', 'front', 'root', 'type', 'del'])
    img = copy.deepcopy(img)
    if kind == 'word':
        return mutate_word(rng, img)
    if kind == 'cells':
        s = rng.randrange(11)
        img['cells'][s] += rng.choice([-2, -1, 1, 2, 4])
        if img['cells'][s] < 0:
            img['cells'][s] = 0
        return img
    if kind == 'rows':
        s = rng.randrange(11)
        if img['banks'][s] and rng.random() < 0.5:
            img['banks'][s].pop()
        else:
            img['banks'][s].append('0' * 64)
        return img
    if kind == 'bitmaps':
        if not img['bitmaps']:
            return None
        i = rng.randrange(len(img['bitmaps']))
        if rng.random() < 0.4:
            img['bitmaps'].pop(i)
        else:
            v = int(img['bitmaps'][i], 16) ^ (1 << rng.randrange(64))
            img['bitmaps'][i] = format(v, '016x')
        return img
    if kind == 'ni':
        if not img['nexthops']:
            return None
        i = rng.randrange(len(img['nexthops']))
        if rng.random() < 0.3:
            img['nexthops'].pop(i)
        else:
            img['nexthops'][i] = rng.randint(0, 4194302)
        return img
    if kind == 'front':
        pool = [img['front16'], img['front64']]
        f = rng.choice(pool)
        if not f:
            return None
        i = rng.randrange(len(f))
        j = rng.randrange(len(f))
        if i != j and rng.random() < 0.5:
            f[i], f[j] = f[j], f[i]
        else:
            f.pop(i)
        return img
    if kind == 'root':
        if img['root'] is None:
            return None
        img['root'] = [rng.randrange(11) if False else rng.randint(0, 10), rng.randrange(3)]
        return img
    if kind == 'type':
        s = rng.randrange(11)
        if not img['banks'][s]:
            return None
        r = rng.randrange(len(img['banks'][s]))
        w = int(img['banks'][s][r], 16)
        w = (w & ~7) | rng.randint(0, 7)
        img['banks'][s][r] = format(w, '064x')
        return img
    if kind == 'del':
        s = rng.randrange(11)
        if not img['banks'][s]:
            return None
        r = rng.randrange(len(img['banks'][s]))
        img['banks'][s][r] = '0' * 64
        return img
    return None


def main():
    binary = cli.build()
    rng = random.Random(int(sys.argv[1]) if len(sys.argv) > 1 else 3)
    rounds = int(sys.argv[2]) if len(sys.argv) > 2 else 5
    for it in range(rounds):
        n = rng.choice([1, 3, 7, 25, 90])
        d = {}
        while len(d) < n:
            hi, lo = rng.getrandbits(64), rng.getrandbits(64)
            l = rng.randint(0, 128)
            hi, lo = pyref.norm(hi, lo, l)
            d[(hi, lo, l)] = rng.randint(0, 4194302)
        base = pyref.build_image(sorted([(k[0], k[1], k[2], v) for k, v in d.items()]), rng)
        assert py_verdict(base) is True
        assert load_verdict(binary, base) is True, 'valid image rejected'
        disagree = 0
        tested = 0
        for m in range(60):
            img = mutate_random(rng, base)
            if img is None or not shape_ok(img):
                continue
            c = load_verdict(binary, img)
            p = py_verdict(img)
            tested += 1
            if c is True and p is not True:
                print('iter', it, 'DISAGREE: C++ accepts, python rejects:', p)
                disagree += 1
                json.dump({'img': img, 'orig': base}, open('disagree%d_%d.json' % (it, m), 'w'))
            elif c is False and p is not False:
                print('iter', it, 'DISAGREE: C++ rejects, python accepts', p)
                disagree += 1
                json.dump({'img': img, 'orig': base}, open('disagree%d_%d.json' % (it, m), 'w'))
        print('iter', it, 'n=%d mutations tested=%d disagreements=%d' % (n, tested, disagree))
        if disagree:
            return 1
    print('ALL OK')
    return 0


if __name__ == '__main__':
    sys.exit(main())
